/* ===== Round 2: admin: category tree, keyword mapping, video moderation ===== */
const _ac2=V.acats;
V.acats=()=>{let h=_ac2();if((UI.act||'cats')!=='scats'||!perm('catalog','view'))return h;
 const tree=`<div class="card pad stack" style="margin-top:16px"><div class="row between wrap-r"><h3>${t('Category tree')}: ${t('Category')} › ${t('Subcategory')} › ${t('Service type')}</h3><button class="btn p sm" data-act="treeAdd" ${dis('catalog')}>${ic('plus',14)} ${t('Add subcategory')}</button></div><p class="small t2">${t('Subcategories you add here appear in the Explore and Search subcategory filter automatically. Keywords link search words to them.')}</p>${D().scats.map(c=>`<details class="acc" ${UI.treeOpen===c.id?'open':''}><summary>${c.e} ${esc(nm(c))} <span class="sfn">${svcSubs(c.id).length}</span>${ic('cd',18)}</summary><div class="stack">${svcSubs(c.id).map(sb=>{const types=D().types[sb.slug]||[],kws=D().kw.filter(k=>k.subs.includes(sb.slug)),n=allServices().filter(s=>s.sub===sb.slug).length;return `<div class="card pad stack" style="gap:6px"><div class="row between wrap-r"><b>${esc(S.lang==='hi'&&sb.hi?sb.hi:sb.en)} <span class="xs muted">· ${n} ${t('services')}</span></b><button class="btn g sm" data-act="treeEdit" data-s="${sb.slug}" ${dis('catalog')}>${ic('edit',14)} ${t('Types & keywords')}</button></div><div class="row wrap-r" style="gap:6px"><span class="xs muted">${t('Service types')}:</span>${types.map(x=>`<span class="badge neu">${esc(x)}</span>`).join('')||`<span class="xs muted">${t('None yet')}</span>`}</div><div class="row wrap-r" style="gap:6px"><span class="xs muted">${t('Keywords')}:</span>${kws.flatMap(k=>k.syn).slice(0,8).map(x=>`<span class="badge info">${esc(x)}</span>`).join('')||`<span class="xs muted">${t('None yet')}</span>`}</div></div>`}).join('')}<button class="btn o sm" data-act="acPreview" data-id="${c.id}" style="justify-self:start">${ic('eye',14)} ${t('Preview filter')}</button></div></details>`).join('')}</div>`;return h+tree};
A.treeAdd=()=>sheet(`<h3>${t('Add subcategory')}</h3><form data-form="treeSub" class="stack" style="margin-top:10px">${field('Category','main',UI.treeOpen||'wedding',{type:'select',opts:SCATS.map(c=>[c.id,c.en])})}${field('Name (English)','en','',{req:1})}${field('Name (Hindi)','hi','')}<button class="btn p">${t('Add subcategory')}</button></form>`);
F.treeSub=d=>{if(similarSub(d.main,d.en)&&similarSub(d.main,d.en).en.toLowerCase()===d.en.trim().toLowerCase()){toast(t('This subcategory already exists'),'alert');return}D().subs.unshift({id:rid('sb'),main:d.main,en:d.en.trim(),hi:d.hi,status:'approved',by:S.role==='super'?'Super Admin':curAdmin().name,byRole:'admin',ts:Date.now()});UI.treeOpen=d.main;audit('Subcategory created',d.en,{},{main:d.main});save();closeSheet();render(true);toast(t('Added. It now shows in the filter.'),'check')};
A.treeEdit=el=>{const sl=el.dataset.s,sb=subInfo(sl),kws=D().kw.filter(k=>k.subs.includes(sl));sheet(`<h3>${esc(sb.en)}</h3><form data-form="treeKw" class="stack" style="margin-top:10px"><input type="hidden" name="s" value="${sl}">${field('Service types (comma separated)','types',(D().types[sl]||[]).join(', '))}${field('Keywords & synonyms (comma separated, include Hindi / Hinglish)','kws',kws.flatMap(k=>k.syn).join(', '),{type:'textarea',ph:'ac, एसी, air conditioner'})}<button class="btn p">${t('Save')}</button></form>`)};
F.treeKw=d=>{const list=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean),sl=d.s,sb=subInfo(sl);D().types[sl]=list(d.types);const syn=list(d.kws);let k=D().kw.find(x=>x.subs.length===1&&x.subs[0]===sl);if(syn.length){if(k)k.syn=syn;else D().kw.push({id:rid('k'),key:syn[0].toLowerCase(),syn,shopCats:[],pcats:[],subs:[sl],tags:[],note:sb.en})}audit('Types & keywords',sb.en,{},{types:D().types[sl].length,keywords:syn.length});save();closeSheet();render(true);toast(t('Saved'),'check')};
/* keyword mapping tool */
UI.kq='ac';
V.akeys=()=>gate('catalog',()=>{const r=UI.kq.trim()?searchAll(UI.kq):{p:[],b:[],s:[],v:[],kws:[]};
 return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Search keywords')}</h1><button class="btn p sm" data-act="kwEdit" data-id="" ${dis('catalog')}>${ic('plus',16)} ${t('Add keyword')}</button></div><p class="t2">${t('Link a search word to categories, subcategories and tags so search can show related products, shops, services and videos.')}</p>
 <div class="card pad stack"><h3>${t('Try a search')}</h3><div class="searchbar">${ic('search',18)}<input data-in="kq" value="${esc(UI.kq)}" placeholder="AC, iPhone 15, एसी, plumbr" aria-label="${t('Test search')}"></div><div id="kqres">${kqHtml(r)}</div></div>
 <div class="stack">${D().kw.map(k=>`<div class="card pad stack"><div class="row between wrap-r"><b style="font-size:1.05rem">${esc(k.key)}</b><div class="row"><button class="btn g sm" data-act="kwEdit" data-id="${k.id}" ${dis('catalog')}>${t('Edit')}</button><button class="btn t sm" data-act="kwDel" data-id="${k.id}" ${dis('catalog')} aria-label="${t('Delete')} ${esc(k.key)}">${ic('trash',16)}</button></div></div><div class="row wrap-r" style="gap:6px"><span class="xs muted">${t('Synonyms')}:</span>${k.syn.map(x=>`<span class="badge neu">${esc(x)}</span>`).join('')}</div><div class="row wrap-r" style="gap:6px"><span class="xs muted">${t('Shop categories')}:</span>${k.shopCats.map(c=>`<span class="badge sec">${esc(catName(c))}</span>`).join('')||'—'}<span class="xs muted">${t('Subcategories')}:</span>${k.subs.map(s=>`<span class="badge info">${esc(subLabel(s))}</span>`).join('')||'—'}${k.tags.length?`<span class="xs muted">${t('Tags')}:</span>${k.tags.map(x=>`<span class="badge neu">#${esc(x)}</span>`).join('')}`:''}</div></div>`).join('')}</div></div>`});
const kqHtml=r=>`<div class="grid g4" style="grid-template-columns:repeat(auto-fit,minmax(120px,1fr))">${[['Products',r.p],['Shops',r.b],['Services',r.s],['Videos',r.v]].map(([l,a])=>`<div class="card pad"><b>${a.length}</b><div class="xs muted">${t(l)}</div><div class="xs truncate">${a.slice(0,2).map(x=>esc(x.name?nm(x.name):x.n||x.m&&x.m.title)).join(', ')}</div></div>`).join('')}</div><div class="small t2">${r.kws.length?t('Matched keywords')+': '+r.kws.map(k=>'<b>'+esc(k.key)+'</b>').join(', '):t('No keyword mapping matched. Results use plain text matching.')}</div>`;
INP.kq=v=>{UI.kq=v;SRCH=null;const q=D().kw;$('#kqres').innerHTML=kqHtml(v.trim()?searchAll(v):{p:[],b:[],s:[],v:[],kws:[]})};
A.kwEdit=el=>{const k=D().kw.find(x=>x.id===el.dataset.id)||{id:'',key:'',syn:[],shopCats:[],subs:[],tags:[],note:''};sheet(`<h3>${k.id?t('Edit keyword'):t('Add keyword')}</h3><form data-form="kw" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${k.id}">${field('Keyword','key',k.key,{req:1})}${field('Synonyms (comma separated)','syn',k.syn.join(', '),{type:'textarea',hint:'Include Hindi and Hinglish spellings'})}<div><div class="lbl small">${t('Shop categories')}</div><div class="chips" style="flex-wrap:wrap">${CATS.map(c=>`<label class="chip"><input type="checkbox" name="sc_${c.id}" ${k.shopCats.includes(c.id)?'checked':''} style="accent-color:var(--primary)"> ${c.e} ${esc(c.en)}</label>`).join('')}</div></div><div><div class="lbl small">${t('Service subcategories')}</div><div class="chips" style="flex-wrap:wrap;max-height:160px;overflow:auto">${SCATS.flatMap(c=>svcSubs(c.id).map(x=>`<label class="chip"><input type="checkbox" name="sb_${x.slug}" ${k.subs.includes(x.slug)?'checked':''} style="accent-color:var(--primary)"> ${esc(x.en)}</label>`)).join('')}</div></div>${field('Product tags (comma separated)','tags',k.tags.join(', '))}${field('Note','note',k.note)}<button class="btn p">${t('Save & preview')}</button></form>`,{wide:true,label:'Keyword'})};
F.kw=d=>{const list=s=>(s||'').split(',').map(x=>x.trim()).filter(Boolean);const o={key:d.key.trim(),syn:[...new Set([d.key.trim(),...list(d.syn)])],shopCats:Object.keys(d).filter(k=>k.startsWith('sc_')).map(k=>k.slice(3)),pcats:Object.keys(d).filter(k=>k.startsWith('sc_')).map(k=>k.slice(3)),subs:Object.keys(d).filter(k=>k.startsWith('sb_')).map(k=>k.slice(3)),tags:list(d.tags),note:d.note};if(d.id)Object.assign(D().kw.find(x=>x.id===d.id),o);else D().kw.push({id:rid('k'),...o});UI.kq=o.key;SRCH=null;audit('Keyword mapping saved',o.key,{},{subs:o.subs.length});save();closeSheet();render(true);toast(t('Saved. Preview updated.'),'check')};
A.kwDel=el=>confirmBox(t('Delete this keyword?'),t('Search will fall back to plain text matching for it.'),t('Delete'),()=>{D().kw=D().kw.filter(k=>k.id!==el.dataset.id);SRCH=null;save();render(true)},true);
/* video moderation */
const ownerVideos=()=>{const o=[];[...D().biz,...D().svc].forEach(x=>(x.media||[]).forEach(m=>o.push({m,o:x})));return o};
UI.avTab='pending';
V.avideos=()=>gate('reviews',()=>{const tab=UI.avTab,all=ownerVideos(),rep=D().vrep,tabs=[['pending','Pending'],['approved','Approved'],['rejected','Rejected'],['removed','Removed'],['reported','Reported'],['engage','Engagement']];
 const cnt=k=>k==='reported'?rep.filter(r=>r.st==='open').length:k==='engage'?all.length:all.filter(v=>v.m.status===k).length;let body='';
 if(tab==='reported')body=rep.length?`<div class="stack">${rep.map(r=>`<div class="card pad stack"><div class="row between wrap-r"><div><b>${esc(r.title)}</b><div class="small t2">${t('Reason')}: ${esc(r.reason)} · ${t('Reported by')} ${esc(r.by)} · ${ago(r.ts)}</div></div><span class="badge ${r.st==='open'?'warn':'ok'}">${t(r.st==='open'?'Open':'Resolved')}</span></div>${r.st==='open'?`<div class="row wrap-r"><button class="btn g sm" data-act="vrepDo" data-id="${r.id}" data-v="dismiss" ${dis('reviews')}>${t('Dismiss')}</button><button class="btn d sm" data-act="vrepDo" data-id="${r.id}" data-v="remove" ${dis('reviews')}>${t('Remove video')}</button></div>`:''}</div>`).join('')}</div>`:empty('✅','No reports','Reported videos show here.');
 else if(tab==='engage')body=tbl(['Video','Owner','Views','Likes','Shares','Taps on linked','Like rate'],all.filter(v=>v.m.status==='approved').map(v=>[esc(v.m.title),esc(nm(v.o.name)),v.m.views.toLocaleString('en-IN'),v.m.likes,v.m.shares,v.m.taps,(v.m.views?Math.round(v.m.likes/v.m.views*100):0)+'%']));
 else{const l=all.filter(v=>v.m.status===tab);body=l.length?`<div class="stack">${l.map(v=>`<div class="card pad stack"><div class="row">${art(v.m.thumb,v.m.t==='yt'?0:330,'mini')}<div class="grow"><b>${esc(v.m.title)}</b><div class="small t2">${esc(nm(v.o.name))} · ${mLabel(v.m)} · ${ago(v.m.ts)}</div></div>${stChip(v.m.status)}</div><div class="small">${esc(v.m.cap)}</div>${v.m.reason?`<div class="small t2">${t('Reason')}: ${esc(v.m.reason)}</div>`:''}<div class="row wrap-r"><button class="btn g sm" data-act="playMedia" data-o="${v.o.id}" data-m="${v.m.id}">${ic('eye',14)} ${t('Preview')}</button>${v.m.status!=='approved'?`<button class="btn p sm" data-act="vmAp" data-o="${v.o.id}" data-m="${v.m.id}" ${dis('reviews')}>${ic('check',14)} ${t('Approve')}</button>`:''}${v.m.status==='pending'?`<button class="btn g sm" data-act="vmRej" data-o="${v.o.id}" data-m="${v.m.id}" ${dis('reviews')}>${ic('x',14)} ${t('Reject')}</button>`:''}${v.m.status!=='removed'?`<button class="btn d sm" data-act="vmRem" data-o="${v.o.id}" data-m="${v.m.id}" ${dis('reviews')}>${t('Remove')}</button>`:''}</div></div>`).join('')}</div>`:empty('✅','Queue is clear','Nothing in this list.')}
 return `<div class="stack"><h1>${t('Videos & moderation')}</h1><div class="chips">${tabs.map(([k,l])=>`<button class="chip ${tab===k?'on':''}" data-act="avTab" data-v="${k}">${t(l)} (${cnt(k)})</button>`).join('')}</div>${body}</div>`});
A.avTab=el=>{UI.avTab=el.dataset.v;render(true)};
const vmFind=el=>{const o=ent(el.dataset.o);return{o,m:o.media.find(x=>x.id===el.dataset.m)}};
const ownerRole=o=>o.id[0]==='s'?'provider':'vendor';
A.vmAp=el=>{const{o,m}=vmFind(el);m.status='approved';m.reason='';notify(ownerRole(o),'Video approved',m.title,'vmedia','admin');audit('Video approved',m.title,{},{status:'approved'});SRCH=null;save();render(true);toast(t('Approved. It is live in Reels and Gallery.'),'check')};
A.vmRej=el=>{const{o,m}=vmFind(el);sheet(`<h3>${t('Reject video')}</h3><form data-form="vmRej" class="stack" style="margin-top:10px"><input type="hidden" name="o" value="${o.id}"><input type="hidden" name="m" value="${m.id}">${field('Reason (sent to the owner)','reason','',{type:'textarea',req:1})}<button class="btn d">${t('Reject')}</button></form>`)};
F.vmRej=d=>{const o=ent(d.o),m=o.media.find(x=>x.id===d.m);m.status='rejected';m.reason=d.reason;notify(ownerRole(o),'Video rejected',m.title+': '+d.reason,'vmedia','admin');audit('Video rejected',m.title,{},{reason:d.reason});save();closeSheet();render(true);toast(t('Rejected. The owner was notified.'))};
A.vmRem=el=>{const{o,m}=vmFind(el);confirmBox(t('Remove this video?'),t('It disappears from Reels, Gallery and search. The owner is notified.'),t('Remove'),()=>{m.status='removed';notify(ownerRole(o),'Video removed',m.title,'vmedia','admin');audit('Video removed',m.title,{},{status:'removed'});SRCH=null;save();render(true)},true)};
A.vrepDo=el=>{const r=D().vrep.find(x=>x.id===el.dataset.id);r.st='resolved';if(el.dataset.v==='remove'){const v=ownerVideos().find(x=>x.m.title===r.title);if(v){v.m.status='removed';notify(ownerRole(v.o),'Video removed after report',v.m.title,'vmedia','admin')}}audit('Video report '+el.dataset.v,r.title,{},{});save();render(true);toast(t('Done'))};
